                  "பல மாநிலங்களில், கூட்டுறவு சங்கங்கள் எவ்வாறு நடத்தப்படுகின்றன என்பதில் அரசாங்கத்திற்கு வலுவான கருத்து இருந்தது — சில நேரங்களில் குழு உறுப்பினர்களைத் தேர்ந்தெடுப்பதிலும் அல்லது தேர்தல்களை தாமதப்படுத்துவதிலும் கூட. இது விவசாயி-உறுப்பினர்களுக்கு இது உண்மையிலேயே \"தங்கள் சொந்த\" வணிகம் என்று உணர்வதை கடினமாக்கியது.",
