                heading: L("Operational: MPP and MPC", "ఆపరేషనల్: MPP, MPC", "செயல்பாட்டு: MPP மற்றும் MPC", "ಕಾರ್ಯಾಚರಣಾ: MPP ಮತ್ತು MPC"),
                html: L(
                  "Every producer member pours milk at their local <b>MPP</b> (Milk Pooling Point). Members at each MPP elect a small committee, sometimes called the <b>MPC</b> (Milk Producer Committee), to represent them. Several MPCs join together into bigger village-cluster groups, so that even a farmer in the smallest village has a representative all the way up.",
                  "ప్రతి ఉత్పత్తిదారు సభ్యుడు తమ స్థానిక <b>MPP</b> (మిల్క్ పూలింగ్ పాయింట్) వద్ద పాలు పోస్తారు. ప్రతి MPP వద్ద సభ్యులు తమను ప్రాతినిధ్యం వహించడానికి <b>MPC</b> (మిల్క్ ప్రొడ్యూసర్ కమిటీ) అని పిలువబడే చిన్న కమిటీని ఎన్నుకుంటారు. అనేక MPCలు పెద్ద గ్రామ-క్లస్టర్ సమూహాలుగా కలిసిపోతాయి, తద్వారా అతి చిన్న గ్రామంలోని రైతుకు కూడా పైవరకు ప్రతినిధి ఉంటాడు.",
                  "ஒவ்வொரு உற்பத்தியாளர் உறுப்பினரும் தங்கள் உள்ளூர் <b>MPP</b> (பால் சேகரிப்பு புள்ளி) இல் பால் ஊற்றுகிறார்கள். ஒவ்வொரு MPP இலும் உள்ள உறுப்பினர்கள் தங்களைப் பிரதிநிதித்துவப்படுத்த <b>MPC</b> (பால் உற்பத்தியாளர் குழு) எனப்படும் ஒரு சிறிய குழுவைத் தேர்ந்தெடுக்கிறார்கள். பல MPC கள் பெரிய கிராம-கொத்து குழுக்களாக இணைகின்றன, இதனால் மிகச் சிறிய கிராமத்தில் உள்ள விவசாயிக்கும் மேல்நிலை வரை ஒரு பிரதிநிதி இருக்கிறார்.",
                  "ಪ್ರತಿ ಉತ್ಪಾದಕ ಸದಸ್ಯರೂ ತಮ್ಮ ಸ್ಥಳೀಯ <b>MPP</b> (ಹಾಲು ಸಂಗ್ರಹ ಕೇಂದ್ರ) ದಲ್ಲಿ ಹಾಲು ಸುರಿಯುತ್ತಾರೆ. ಪ್ರತಿ MPP ಯಲ್ಲಿನ ಸದಸ್ಯರು ತಮ್ಮನ್ನು ಪ್ರತಿನಿಧಿಸಲು <b>MPC</b> (ಹಾಲು ಉತ್ಪಾದಕ ಸಮಿತಿ) ಎಂದು ಕರೆಯಲ್ಪಡುವ ಚಿಕ್ಕ ಸಮಿತಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡುತ್ತಾರೆ. ಹಲವಾರು MPC ಗಳು ದೊಡ್ಡ ಗ್ರಾಮ-ಗುಚ್ಛ ಗುಂಪುಗಳಾಗಿ ಒಟ್ಟುಗೂಡುತ್ತವೆ, ಇದರಿಂದ ಅತಿ ಚಿಕ್ಕ ಗ್ರಾಮದ ರೈತನಿಗೂ ಮೇಲಿನವರೆಗೆ ಪ್ರತಿನಿಧಿ ಇರುತ್ತಾನೆ."
                ),
