                  "MPO యొక్క అన్ని సభ్యులు కలిసి <b>జనరల్ బాడీ</b>ని ఏర్పరుస్తారు — దాని అత్యున్నత నిర్ణయాత్మక సమూహం. జనరల్ బాడీ <b>డైరెక్టర్ల బోర్డు</b>ను ఎన్నుకుంటుంది, వారు ప్రతి సభ్యుడి తరపున విధానాన్ని నిర్ణయిస్తారు, కంపెనీని పర్యవేక్షిస్తారు.",
