                  "தினசரி செயல்பாடுகளை நிர்வகிக்க குழு ஒரு <b>தலைமை நிர்வாகி (CEO)</b> ஐ நியமிக்கிறது. CEO க்குக் கீழே செயல்பாட்டு தலைவர்கள் உள்ளனர் — உதாரணமாக, கொள்முதல், தர சோதனை, அல்லது நிதிக்குப் பொறுப்பான ஊழியர்கள் — மற்றும் சகாயக்கள் போன்ற கள ஊழியர்கள், அவர்கள் ஒவ்வொரு நாளும் நேரடியாக விவசாயிகளுடன் பணிபுரிகிறார்கள்.",
                  "ದೈನಂದಿನ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ನಿರ್ವಹಿಸಲು ಮಂಡಳಿ <b>ಮುಖ್ಯ ಕಾರ್ಯನಿರ್ವಾಹಕ (CEO)</b> ಅನ್ನು ನೇಮಿಸುತ್ತದೆ. CEO ಕೆಳಗೆ ಕಾರ್ಯಾತ್ಮಕ ಮುಖ್ಯಸ್ಥರು ಇರುತ್ತಾರೆ — ಉದಾಹರಣೆಗೆ, ಖರೀದಿ, ಗುಣಮಟ್ಟ ಪರೀಕ್ಷೆ, ಅಥವಾ ಹಣಕಾಸಿನ ಉಸ್ತುವಾರಿ ಹೊಂದಿರುವ ಸಿಬ್ಬಂದಿ — ಮತ್ತು ಸಹಾಯಕ್‌ಗಳಂತಹ ಕ್ಷೇತ್ರ ಸಿಬ್ಬಂದಿ, ಅವರು ಪ್ರತಿದಿನ ನೇರವಾಗಿ ರೈತರೊಂದಿಗೆ ಕೆಲಸ ಮಾಡುತ್ತಾರೆ."
