                  "సభ్యుడిగా ఉండటం ఒకసారి సైన్-అప్ మాత్రమే కాదు. సభ్యులు క్రియాశీలంగా ఉండాలని ఆశిస్తారు — క్రమం తప్పకుండా పాలు సరఫరా చేయడం, సమావేశాలలో పాల్గొనడం. ఒకసారి చేరి, ప్రయోజనాలు తీసుకుని, పాలు సరఫరా చేయని లేదా రాని వ్యక్తి <b>ఉచిత రైడర్</b>.",
