                  "MPO கள் MPP இல் ஒவ்வொரு உறுப்பினரின் ஆதரவு விவரங்களைக் காட்டுகின்றன, சரியான நேரத்தில் பங்கு சான்றிதழ்களை வழங்குகின்றன, லாபங்கள் பற்றிய தகவல்களைப் பகிர்கின்றன — இதனால் உறுப்பினர்கள் அவர்கள் கொடுப்பதற்கும் அவர்கள் சொந்தமாக்கியிருப்பதற்கும் இடையிலான தொடர்பைப் பார்த்து நம்பலாம்.",
