                  "అన్ని సభ్యులు ఒకే మొత్తంలో పాలు సరఫరా చేయరు. కాబట్టి MPO సభ్యులను వారు సరఫరా చేసే పాల (ప్రోత్సాహం) మొత్తం ఆధారంగా వివిధ <b>తరగతులు</b>గా వర్గీకరించి, ప్రతి తరగతికి బోర్డులో న్యాయమైన ప్రాతినిధ్యం ఇవ్వవచ్చు.",
