                  "வணிகத்தின் ஒவ்வொரு பகுதியும் <b>SOP கள்</b> (நிலையான செயல்பாட்டு நடைமுறைகள்) பயன்படுத்தி எப்படி வேலை செய்கிறது என்பதை தரப்படுத்துகிறார்கள், கணக்கியல் நடைமுறைகளை சரிபார்க்க தர தணிக்கையாளர்களை பணியமர்த்துகிறார்கள், வணிகம் எவ்வாறு செயல்படுகிறது என்பதை குழு தொடர்ந்து மதிப்பாய்வு செய்கிறது — சந்தை வாரியாக, தயாரிப்பு வாரியாக.",
