                  "42 గ్రామాలలోని పాల ఉత్పత్తిదారులకు వారి పాల కోసం వ్యవస్థీకృత, న్యాయమైన మార్కెట్‌ను ఇవ్వడానికి ప్రగతి మిల్క్ ప్రొడ్యూసర్ కంపెనీ లిమిటెడ్ (PMPC) 2018లో స్థాపించబడింది. కల: రైతులు కేవలం పాలు అమ్మడమే కాదు, నిజంగా వ్యాపారాన్ని స్వంతం చేసుకుంటారు.",
                  "42 கிராமங்களில் உள்ள பால் உற்பத்தியாளர்களுக்கு அவர்களின் பாலுக்கு ஒழுங்கமைக்கப்பட்ட, நியாயமான சந்தையை வழங்க பிரகதி பால் உற்பத்தியாளர் நிறுவனம் லிமிடெட் (PMPC) 2018 இல் அமைக்கப்பட்டது. கனவு: விவசாயிகள் பாலை விற்பது மட்டுமல்ல, உண்மையிலேயே வணிகத்தை சொந்தமாக்குவார்கள்.",
                  "42 ಗ್ರಾಮಗಳಲ್ಲಿನ ಹಾಲು ಉತ್ಪಾದಕರಿಗೆ ಅವರ ಹಾಲಿಗೆ ಸಂಘಟಿತ, ನ್ಯಾಯಯುತ ಮಾರುಕಟ್ಟೆ ನೀಡಲು ಪ್ರಗತಿ ಹಾಲು ಉತ್ಪಾದಕ ಕಂಪನಿ ಲಿಮಿಟೆಡ್ (PMPC) 2018 ರಲ್ಲಿ ಸ್ಥಾಪಿಸಲಾಯಿತು. ಕನಸು: ರೈತರು ಕೇವಲ ಹಾಲು ಮಾರುವುದಷ್ಟೇ ಅಲ್ಲ, ನಿಜವಾಗಿಯೂ ವ್ಯವಹಾರವನ್ನು ಸ್ವಂತಗೊಳಿಸುತ್ತಾರೆ."
