                  "5 ರೈತರು ಪ್ರತಿಯೊಬ್ಬರೂ 5 ವಿಭಿನ್ನ ದಿನಗಳಲ್ಲಿ ಒಂದೇ ಪ್ರಶ್ನೆ ಕೇಳಿದರೆ, ನೀವು ಅದಕ್ಕೆ 5 ಬಾರಿ ಉತ್ತರಿಸುತ್ತೀರಿ — ಪ್ರತಿ ಉತ್ತರವೂ ಸ್ವಲ್ಪ ಭಿನ್ನವಾಗಿ ಬರಬಹುದು. ಬದಲಿಗೆ ಒಂದು ಸಭೆ ಕರೆದರೆ, ನೀವು ಒಮ್ಮೆ ಉತ್ತರಿಸುತ್ತೀರಿ, ಎಲ್ಲರೂ ಒಂದೇ ಸರಿಯಾದ ಉತ್ತರವನ್ನು ಒಟ್ಟಿಗೆ ಕೇಳುತ್ತಾರೆ."
