                  "வழித்தடத்தை திட்டமிடுபவர் இரண்டு விஷயங்களை சமநிலைப்படுத்த வேண்டும்: முடிந்தவரை அதிக கிராமங்களை உள்ளடக்குதல், மொத்த பயணத்தை மிக நீளமாக்காமல், இதனால் வாகனம் குளிரூட்டும் மையத்தை அடைவதற்கு முன்பே முதலில் சேகரிக்கப்பட்ட பால் கெட்டுவிடாமல்.",
