                  "రైతు స్వంత బ్యాంకు ఖాతా ఫైల్‌లో ఉన్నప్పుడు, ప్రతిసారీ చెల్లింపు వారికే స్వయంచాలకంగా వెళుతుంది. వారి తెలియకుండా వేరే ఎవరూ వారి తరపున డబ్బు తీసుకోలేరు. నమోదు రైతుకు ఇచ్చే అతిపెద్ద రక్షణలలో ఇది ఒకటి.",
                  "ஒரு விவசாயியின் சொந்த வங்கிக் கணக்கு கோப்பில் இருக்கும்போது, ஒவ்வொரு முறையும் பணம் தானாகவே அவருக்கே செல்கிறது. அவருக்குத் தெரியாமல் வேறு யாரும் அவர் சார்பாக பணத்தை பெற முடியாது. சேர்க்கை ஒரு விவசாயிக்கு தரும் மிகப்பெரிய பாதுகாப்புகளில் இதுவும் ஒன்று.",
                  "ರೈತನ ಸ್ವಂತ ಬ್ಯಾಂಕ್ ಖಾತೆ ಫೈಲ್‌ನಲ್ಲಿದ್ದಾಗ, ಪ್ರತಿ ಬಾರಿಯೂ ಪಾವತಿ ಅವರಿಗೇ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಹೋಗುತ್ತದೆ. ಅವರ ಅರಿವಿಲ್ಲದೆ ಬೇರೆ ಯಾರೂ ಅವರ ಪರವಾಗಿ ಹಣ ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ. ನೋಂದಣಿ ರೈತನಿಗೆ ನೀಡುವ ದೊಡ್ಡ ರಕ್ಷಣೆಗಳಲ್ಲಿ ಇದೂ ಒಂದು."
