                  "CDA எந்த இடைவெளியையும் கண்டறிய கூட்டு (MPP இல் பதிவு செய்யப்பட்டது), அனுப்புதல் (அனுப்பப்பட்டது) மற்றும் உண்மையான (குளிரூட்டும் மையத்தில் பெறப்பட்டது) அளவுகளை ஒப்பிடுகிறது.",
