                  "సగటు రేటు = కాంపోజిట్ మొత్తం ÷ కాంపోజిట్ పరిమాణం = ₹44,00,000 ÷ 1,00,000 లీటర్లు = లీటరుకు ₹44. ఇది ప్రతి లీటరుకు సగటున ఎంత చెల్లించారో చెబుతుంది — కానీ ఆ ధర పాల నిజమైన నాణ్యతకు సరిపోతుందో లేదో ఇంకా చెప్పదు.",
