                  "கையாளுதல் செலவுகள் அதிகமாக இருந்தால், விவசாயிகளுக்கு நல்ல விலை செலுத்தவோ அல்லது வணிகத்தை வளர்க்க முதலீடு செய்யவோ குறைந்த பணம் மிச்சமிருக்கும். கையாளுதல் செலவுகள் திறமையாக வைக்கப்பட்டால், சிறந்த விவசாயி விலைகள், சிறந்த உள்கட்டமைப்பு, வலுவான, நிலையான பால் ஆலைக்கு அதிக பணம் மிச்சமிருக்கும்.",
