                text: L(
                  "Higher milk volumes reduce the cost per litre, because fixed costs — like rent for a chilling centre — get spread across more litres. That is one reason why increasing how much milk each MPP collects is so valuable.",
                  "ఎక్కువ పాల పరిమాణం లీటరుకు ఖర్చును తగ్గిస్తుంది, ఎందుకంటే స్థిర ఖర్చులు — చిల్లింగ్ కేంద్రం అద్దె వంటివి — ఎక్కువ లీటర్లలో పంచుకుంటాయి. ప్రతి MPP సేకరించే పాల పరిమాణాన్ని పెంచడం ఎందుకు విలువైనదో ఇది ఒక కారణం.",
                  "அதிக பால் அளவு ஒரு லிட்டருக்கான செலவை குறைக்கிறது, ஏனெனில் நிலையான செலவுகள் — குளிரூட்டும் மையத்திற்கான வாடகை போன்றவை — அதிக லிட்டர்களில் பரவுகின்றன. ஒவ்வொரு MPP சேகரிக்கும் பாலின் அளவை அதிகரிப்பது ஏன் மிகவும் மதிப்புமிக்கது என்பதற்கு இது ஒரு காரணம்.",
                  "ಹೆಚ್ಚು ಹಾಲಿನ ಪ್ರಮಾಣ ಪ್ರತಿ ಲೀಟರ್‌ಗೆ ವೆಚ್ಚ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ, ಏಕೆಂದರೆ ಸ್ಥಿರ ವೆಚ್ಚಗಳು — ತಂಪಾಗಿಸುವ ಕೇಂದ್ರದ ಬಾಡಿಗೆಯಂತಹವು — ಹೆಚ್ಚು ಲೀಟರ್‌ಗಳಲ್ಲಿ ಹಂಚಲ್ಪಡುತ್ತವೆ. ಪ್ರತಿ MPP ಸಂಗ್ರಹಿಸುವ ಹಾಲಿನ ಪ್ರಮಾಣ ಹೆಚ್ಚಿಸುವುದು ಏಕೆ ಮೌಲ್ಯಯುತ ಎಂಬುದಕ್ಕೆ ಇದೂ ಒಂದು ಕಾರಣ."
                ),
