                text: L(
                  "Spillage, pilferage and quality problems don't just lose milk — they quietly inflate the real cost of handling every litre that does arrive safely. Careful handling protects both quantity and cost.",
                  "ఒలికిపోవడం, దొంగతనం, నాణ్యత సమస్యలు కేవలం పాలను కోల్పోవడమే కాదు — సురక్షితంగా చేరే ప్రతి లీటరు నిర్వహణ నిజమైన ఖర్చును నిశ్శబ్దంగా పెంచుతాయి. జాగ్రత్తగా నిర్వహించడం పరిమాణం, ఖర్చు రెండింటినీ రక్షిస్తుంది.",
                  "சிந்துதல், திருட்டு மற்றும் தர பிரச்சனைகள் பாலை இழக்கச் செய்வது மட்டுமல்ல — பாதுகாப்பாக வரும் ஒவ்வொரு லிட்டரையும் கையாளும் உண்மையான செலவை அமைதியாக அதிகரிக்கின்றன. கவனமான கையாளுதல் அளவையும் செலவையும் பாதுகாக்கிறது.",
                  "ಚೆಲ್ಲುವಿಕೆ, ಕಳ್ಳತನ ಮತ್ತು ಗುಣಮಟ್ಟದ ಸಮಸ್ಯೆಗಳು ಕೇವಲ ಹಾಲನ್ನು ಕಳೆದುಕೊಳ್ಳುವುದಿಲ್ಲ — ಸುರಕ್ಷಿತವಾಗಿ ಬರುವ ಪ್ರತಿ ಲೀಟರ್ ನಿರ್ವಹಣೆಯ ನಿಜವಾದ ವೆಚ್ಚವನ್ನು ಮೌನವಾಗಿ ಹೆಚ್ಚಿಸುತ್ತವೆ. ಎಚ್ಚರಿಕೆಯ ನಿರ್ವಹಣೆ ಪ್ರಮಾಣ ಮತ್ತು ವೆಚ್ಚ ಎರಡನ್ನೂ ರಕ್ಷಿಸುತ್ತದೆ."
                ),
