                  "ஒரு BMC மாதத்திற்கு ₹35,000 செலவில் இயங்குகிறது என்று வைத்துக்கொள்வோம், அதன் வழியாக எவ்வளவு பால் சென்றாலும். அந்த மாதம் 50,000 லிட்டர் கையாண்டால், நிலையான செலவு ஒரு லிட்டருக்கு ₹0.70 ஆகிறது. வெறும் 25,000 லிட்டர் மட்டும் கையாண்டால், அதே ₹35,000 இப்போது ஒரு லிட்டருக்கு ₹1.40 ஆகிறது — குறைவான பால் சென்றதால் மட்டுமே செலவு இரட்டிப்பு.",
